import fs from 'fs';
import path from 'path';
import { RspackConfigMutator, RspackConfigTransformer } from '@teambit/rspack.modules.rspack-config-mutator';
import { ERROR_EVENT } from '@teambit/ui-foundation.ui.rendering.html';

/**
 * Creates an RSPack transformer that injects the error reporting script
 * into HTML files via a custom RSPack plugin using processAssets hook.
 */
export function createErrorReportingTransformer(): RspackConfigTransformer {
  return (configMutator: RspackConfigMutator) => {
    const config = configMutator.raw;

    let errorReportingScript: string;
    try {
      const scriptPath = path.resolve(__dirname, './bit-error-reporting.js');
      errorReportingScript = fs.readFileSync(scriptPath, 'utf8');
      errorReportingScript = errorReportingScript.replace(/\$\{ERROR_EVENT\}/g, ERROR_EVENT);
    } catch (error) {
      console.warn('Failed to load error reporting script:', error);
      errorReportingScript = `
        (function() {
          if (window.parent && window !== window.parent) {
            window.addEventListener('error', function(event) {
              window.parent.postMessage({
                event: '${ERROR_EVENT}',
                payload: {
                  message: event.message || 'Unknown error',
                  filename: event.filename,
                  type: 'runtime-error',
                  context: { url: window.location.href }
                }
              }, '*');
            }, true);
          }
        })();
      `;
    }

    const scriptTag = `<script>${errorReportingScript}</script>`;

    config.plugins = config.plugins || [];
    config.plugins.push({
      name: 'BitErrorReportingPlugin',
      apply(compiler: any) {
        compiler.hooks.compilation.tap('BitErrorReportingPlugin', (compilation: any) => {
          compilation.hooks.processAssets.tap(
            {
              name: 'BitErrorReportingPlugin',
              stage: compiler.webpack.Compilation.PROCESS_ASSETS_STAGE_OPTIMIZE_INLINE,
            },
            (assets: Record<string, any>) => {
              Object.entries(assets)
                .filter(([filename]) => filename.endsWith('.html'))
                .forEach(([filename, asset]) => {
                  const originalSource = asset.source();
                  const updatedSource = originalSource.replace('<head>', `<head>${scriptTag}`);
                  compilation.updateAsset(
                    filename,
                    new compiler.webpack.sources.RawSource(updatedSource)
                  );
                });
            }
          );
        });
      },
    });

    return configMutator;
  };
}
